// ---------- dil desteği: Türkçe (asıl), İngilizce, İspanyolca ----------
// Kod Türkçe yazılır; İngilizce/İspanyolca seçilince ekrandaki yazılar sözlükle çevrilir (DOM çevirmeni).
// Maç anlatımı gibi üretilen cümleler için veri (TXT, konuşmalar) doğrudan dile göre değiştirilir.
const LANGS = { tr:"🇹🇷 Türkçe", en:"🇬🇧 English", es:"🇪🇸 Español" };
const detectLang = () => { try { const l=(navigator.language||"tr").slice(0,2).toLowerCase(); return l==="tr"?"tr":l==="es"?"es":"en"; } catch(e){ return "tr"; } };
const LANG = (() => { const s = store.get("dil", null); return LANGS[s] ? s : (typeof navigator!=="undefined" && typeof location!=="undefined" && location.protocol.startsWith("http") ? detectLang() : "tr"); })();
const LI = LANG==="en" ? 0 : 1;
function setLang(k){ store.set("dil", k); try { location.reload(); } catch(e){} }
function langChips(){ return Object.entries(LANGS).map(([k,v])=>`<button class="chip ${k===LANG?"on":""}" onclick="setLang('${k}')">${v}</button>`).join(""); }

