// "kenar" sembollerini ayırıp çekirdeği çevir
const EDGE = /^([🧪⚙🔊🔇🌐⚗\s ·•✕↺▶✓⚠✅❌⚽🔁🟥🟨🚑📋🎲🧠⚔️🔥📒🗓️🎮👑🏅📸📤⬇️🧘🤝☝️🎯⚡🏹🪽🚀🚌⚖️🌙🟩📺🎱🥅🗣️🏁🟢⏸️⏱️💔🚩➕📲️‍]*)([\s\S]*?)([\s ▶✓⚠…️]*)$/u;
function tcore(s){
  if (!s) return s;
  if (DICT[s]) return DICT[s][LI];
  const e = s.match(EDGE);
  if (e && (e[1]||e[3]) && e[2]){ const c = tcore(e[2]); if (c!==e[2]) return e[1]+c+e[3]; }
  if (s.includes(" · ")){ const parts = s.split(" · "), out = parts.map(tcore); if (out.some((x,i)=>x!==parts[i])) return out.join(" · "); }
  for (const [re, fn] of RX){ const m = s.match(re); if (m) return fn(m); }
  if (/^[A-ZÇĞİÖŞÜ]+(\/[A-ZÇĞİÖŞÜ]+)*$/.test(s)){ const ps = s.split("/"); if (ps.every(p=>POS_I18N[p])) return ps.map(p=>POS_I18N[p][LI]).join("/"); }
  return s;
}
function L(s){ if (LANG==="tr" || s==null) return s; s=String(s); const m = s.match(/^(\s*)([\s\S]*?)(\s*)$/); return m[1]+tcore(m[2])+m[3]; }
const Lines = s => LANG==="tr" ? s : String(s).split("\n").map(L).join("\n");

function translateNode(n){
  if (n.nodeType===3){ const v=n.nodeValue; if (!v || !v.trim()) return; const t=L(v); if (t!==v) n.nodeValue=t; return; }
  if (n.nodeType!==1 || /^(SCRIPT|STYLE)$/.test(n.tagName)) return;
  for (const a of ["placeholder","title"]) if (n.hasAttribute && n.hasAttribute(a)){ const v=n.getAttribute(a), t=L(v); if (t!==v) n.setAttribute(a,t); }
  for (const c of n.childNodes) translateNode(c);
}
function startI18n(){
  if (LANG==="tr" || typeof document==="undefined" || typeof MutationObserver==="undefined" || !document.body) return;
  document.documentElement.lang = LANG;
  translateNode(document.body); document.title = L(document.title);
  new MutationObserver(ms => { for (const m of ms){ if (m.type==="characterData") translateNode(m.target); else for (const n of m.addedNodes) translateNode(n); } })
    .observe(document.body, {subtree:true, childList:true, characterData:true});
  try { const ft = CanvasRenderingContext2D.prototype.fillText; CanvasRenderingContext2D.prototype.fillText = function(t, ...a){ return ft.call(this, L(String(t)), ...a); }; } catch(e){}
}
